// Helpers for the DOF changes pages. The data (dof-changes.json) is generated by
// scripts/build-dof-changes.mjs from the instrument inventory and the extracted Tarifa rows.

let cache = null;
export const loadDofChanges = () => {
  cache ||= import('./dof-changes.json').then((module) => module.default);
  return cache;
};

const SECTION_GROUP = {
  original: 'law',
  law_reform: 'law',
  tariff_decree: 'tariff',
  tariff_decree_modification: 'tariff',
  complementary: 'agreement',
  complementary_modification: 'agreement',
};
export const groupOf = (section) => SECTION_GROUP[section] || 'tariff';

export const SECTION_LABELS = {
  es: { original: 'Ley original', law_reform: 'Reforma a la Ley', tariff_decree: 'Decreto de Tarifa', tariff_decree_modification: 'Modificación a un decreto', complementary: 'Acuerdo complementario', complementary_modification: 'Modificación a un acuerdo' },
  en: { original: 'Original law', law_reform: 'Law reform', tariff_decree: 'Tariff decree', tariff_decree_modification: 'Decree amendment', complementary: 'Complementary agreement', complementary_modification: 'Agreement amendment' },
};

export const OPERATION_LABELS = {
  es: { temporary_rate: 'Tasa temporal', modify_rate: 'Modifica tasas', sector_program: 'Programa sectorial', quota_rate: 'Arancel-cupo', extend_validity: 'Amplía la vigencia', create: 'Crea fracciones', add_chapter_note: 'Agrega nota de capítulo', remove_from_decree: 'Retira fracciones del decreto', abrogation: 'Abroga', nico_create: 'Crea NICO', nico_suppress: 'Suprime NICO', nico_annotation: 'Anota NICO', nico_base: 'Base de NICO', derogation: 'Deroga', national_notes: 'Notas nacionales', staged_rate: 'Tasas escalonadas', correlation: 'Tablas de correlación', base: 'Ley original' },
  en: { temporary_rate: 'Temporary rate', modify_rate: 'Rate change', sector_program: 'Sector program', quota_rate: 'Tariff-rate quota', extend_validity: 'Extends validity', create: 'Creates fractions', add_chapter_note: 'Adds a chapter note', remove_from_decree: 'Removes fractions from a decree', abrogation: 'Repeals', nico_create: 'Creates NICO', nico_suppress: 'Suppresses NICO', nico_annotation: 'Annotates NICO', nico_base: 'NICO base', derogation: 'Derogates', national_notes: 'National notes', staged_rate: 'Staged rates', correlation: 'Correlation tables', base: 'Original law' },
};
export const operationLabel = (operation, language) => OPERATION_LABELS[language === 'en' ? 'en' : 'es'][operation] || operation;

// The DOF day edition: the exact note needs a code the dataset does not hold yet.
export const dofEditionUrl = (isoDate) => {
  const [year, month, day] = isoDate.split('-');
  return `https://www.dof.gob.mx/index.php?year=${year}&month=${month}&day=${day}`;
};

export const formatDate = (isoDate, language) => {
  const [year, month, day] = isoDate.split('-').map(Number);
  return new Date(Date.UTC(year, month - 1, day)).toLocaleDateString(language === 'en' ? 'en-US' : 'es-MX', { year: 'numeric', month: 'long', day: 'numeric', timeZone: 'UTC' });
};

export const rateLabel = (value) => {
  if (value === null || value === undefined || value === '') return '—';
  return /^ex/i.test(String(value)) ? 'Ex.' : `${value}%`;
};

export const instrumentCodes = (instrument) => (instrument.rate_rows ? instrument.rate_rows.map((row) => row[0]) : instrument.codes || []);

export const chaptersOf = (instrument) => [...new Set(instrumentCodes(instrument).map((code) => code.slice(0, 2)))].sort();

export const countFractions = (instrument) => instrumentCodes(instrument).length;

// Instruments that touch a code or a code prefix, with the rate they set when it is published.
export function findByCode(instruments, input) {
  const digits = String(input || '').replace(/\D/g, '');
  if (digits.length < 2) return [];
  return instruments.flatMap((instrument) => {
    const rows = instrument.rate_rows ? instrument.rate_rows.filter((row) => row[0].startsWith(digits)) : [];
    const codes = !instrument.rate_rows && instrument.codes ? instrument.codes.filter((code) => code.startsWith(digits)) : [];
    if (!rows.length && !codes.length) return [];
    return [{ instrument, rows, codes, exact: digits.length >= 8 }];
  });
}
